WITH prev_events AS (SELECT *, LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time ASC, id ASC) AS prev_txn_time FROM transactions), with_gaps AS (SELECT *, CASE WHEN prev_txn_time IS NULL OR txn_time > prev_txn_time + INTERVAL 7 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM prev_events), islands AS (SELECT id, txn_type, amount, txn_time, merchant, is_flagged, SUM(new_group_flag) OVER (PARTITION BY txn_type ORDER BY txn_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM with_gaps) SELECT id, txn_type, amount, is_flagged, CASE WHEN txn_type RLIKE '^(CREDIT|DEBIT)$' THEN 'GROUP_B' WHEN txn_type RLIKE '^(REFUND|FEE)$' THEN 'OTHER_ZONE' ELSE 'CORE' END AS txn_type_zone FROM islands
